#!/usr/bin/env python3
"""A small, self-contained command benchmarker.

All command execution, measurement, parsing, and serialization are implemented
here using the standard library. The generated zip application needs no assets
outside itself.
"""
import csv
import decimal
import errno
import io
import itertools
import json
import math
import os
import re
import resource
import signal
import statistics
import subprocess
import sys
import time
import zipfile
from dataclasses import dataclass, field


class Failure(Exception):
    pass


class CliExit(Exception):
    def __init__(self, text, code=2, stdout=False):
        self.text, self.code, self.stdout = text, code, stdout


@dataclass
class Option:
    long: str
    short: str = ''
    value: str = ''
    arity: int = 1
    repeated: bool = False
    choices: tuple = ()
    optional: bool = False

    @property
    def label(self):
        name = '--' + self.long if self.long != 'no-shell' else '-N'
        if self.optional:
            return name + '[=<MODE>]'
        return name + (' ' + self.value if self.value else '')


OPTIONS = [
    Option('warmup', 'w', '<NUM>'),
    Option('min-runs', 'm', '<NUM>'),
    Option('max-runs', 'M', '<NUM>'),
    Option('runs', 'r', '<NUM>'),
    Option('setup', 's', '<CMD>'),
    Option('reference', '', '<CMD>'),
    Option('reference-name', '', '<CMD>'),
    Option('prepare', 'p', '<CMD>', repeated=True),
    Option('conclude', 'C', '<CMD>', repeated=True),
    Option('cleanup', 'c', '<CMD>'),
    Option('parameter-scan', 'P', '<VAR> <MIN> <MAX>', 3),
    Option('parameter-step-size', 'D', '<DELTA>'),
    Option('parameter-list', 'L', '<VAR> <VALUES>', 2, repeated=True),
    Option('shell', 'S', '<SHELL>'),
    Option('no-shell', 'N', arity=0),
    Option('ignore-failure', 'i', '<MODE>', optional=True),
    Option('style', '', '<TYPE>', choices=('auto', 'basic', 'full', 'nocolor', 'color', 'none')),
    Option('sort', '', '<METHOD>', choices=('auto', 'command', 'mean-time')),
    Option('time-unit', 'u', '<UNIT>', choices=('microsecond', 'millisecond', 'second')),
    Option('export-asciidoc', '', '<FILE>'),
    Option('export-csv', '', '<FILE>'),
    Option('export-json', '', '<FILE>'),
    Option('export-markdown', '', '<FILE>'),
    Option('export-orgmode', '', '<FILE>'),
    Option('show-output', arity=0),
    Option('output', '', '<WHERE>', repeated=True),
    Option('input', '', '<WHERE>'),
    Option('command-name', 'n', '<NAME>', repeated=True),
    Option('help', 'h', arity=0),
    Option('version', 'V', arity=0),
]
LONG = {o.long: o for o in OPTIONS if o.long != 'no-shell'}
BY_NAME = {o.long: o for o in OPTIONS}
SHORT = {o.short: o for o in OPTIONS if o.short}
CONFLICTS = [
    ('runs', 'min-runs'), ('runs', 'max-runs'),
    ('shell', 'no-shell'), ('parameter-scan', 'parameter-list'),
    ('style', 'show-output'), ('output', 'show-output'),
]
DEPENDENCIES = {'parameter-step-size': 'parameter-scan', 'reference-name': 'reference'}
FOOTER = "For more information, try '--help'.\n"


def program_name():
    name = os.path.basename(sys.argv[0])
    return 'executable' if name in ('__main__.py', 'main.py') else name


def read_help():
    if os.path.isfile(sys.argv[0]) and zipfile.is_zipfile(sys.argv[0]):
        with zipfile.ZipFile(sys.argv[0]) as z:
            text = z.read('help.txt').decode()
    else:
        with open(os.path.join(os.path.dirname(__file__), 'help.txt'), encoding='utf-8') as f:
            text = f.read()
    return text.replace('Usage: executable ', 'Usage: ' + program_name() + ' ')


def jaro_winkler(a, b):
    """Similarity used only for friendly spelling suggestions."""
    if a == b:
        return 1.0
    if not a or not b:
        return 0.0
    distance = max(len(a), len(b)) // 2 - 1
    distance = max(0, distance)
    am, bm = [False] * len(a), [False] * len(b)
    for i, char in enumerate(a):
        for j in range(max(0, i - distance), min(len(b), i + distance + 1)):
            if not bm[j] and char == b[j]:
                am[i], bm[j] = True, True
                break
    count = sum(am)
    if not count:
        return 0.0
    aa = [c for c, m in zip(a, am) if m]
    bb = [c for c, m in zip(b, bm) if m]
    transpositions = sum(x != y for x, y in zip(aa, bb)) / 2
    score = (count / len(a) + count / len(b) + (count - transpositions) / count) / 3
    prefix = 0
    for x, y in zip(a, b):
        if x != y or prefix == 4:
            break
        prefix += 1
    return score + (prefix * 0.1 * (1 - score) if score > 0.7 else 0)


def suggestion(value, values):
    matches = sorted(((jaro_winkler(value, x), x) for x in values), reverse=True)
    return matches[0][1] if matches and matches[0][0] > 0.8 else None


class Parser:
    def __init__(self):
        self.values = {}
        self.seen = []
        self.commands = []

    def usage(self, names=None):
        if names is None:
            return 'Usage: ' + program_name() + ' [OPTIONS] <command>...'
        ordered = []
        for name in names:
            dep = DEPENDENCIES.get(name)
            if dep and dep not in ordered and dep not in names:
                ordered.append(dep)
            if name not in ordered:
                ordered.append(name)
        return 'Usage: ' + program_name() + ' ' + ' '.join(
            [BY_NAME[n].label for n in ordered] + ['<command>...'])

    def fail(self, message, usage=None, tips=''):
        text = 'error: ' + message + '\n'
        if tips:
            text += '\n' + tips + '\n'
        if usage is not False:
            text += '\n' + self.usage(usage) + '\n'
        text += '\n' + FOOTER
        raise CliExit(text)

    def unexpected(self, arg):
        possible = suggestion(arg[2:], LONG) if arg.startswith('--') else None
        if possible:
            tips = "  tip: a similar argument exists: '--" + possible + "'"
            names = self.seen + [possible]
        else:
            tips = f"  tip: to pass '{arg}' as a value, use '-- {arg}'"
            names = None
        self.fail(f"unexpected argument '{arg}' found", names, tips)

    def missing_value(self, opt):
        text = f"error: a value is required for '{opt.label}' but none was supplied\n"
        if opt.choices:
            text += '  [possible values: ' + ', '.join(opt.choices) + ']\n'
        raise CliExit(text + '\n' + FOOTER)

    def accept(self, opt, vals):
        name = opt.long
        if name in self.values and not opt.repeated:
            self.fail(f"the argument '{opt.label}' cannot be used multiple times")
        if opt.choices:
            value = vals[0]
            if not value:
                self.missing_value(opt)
            if value not in opt.choices:
                text = f"error: invalid value '{value}' for '{opt.label}'\n"
                text += '  [possible values: ' + ', '.join(opt.choices) + ']\n'
                match = suggestion(value, opt.choices)
                if match:
                    text += f"\n  tip: a similar value exists: '{match}'\n"
                raise CliExit(text + '\n' + FOOTER)
        if name == 'help':
            raise CliExit(read_help(), 0, True)
        if name == 'version':
            raise CliExit('hyperfine 1.20.0\n', 0, True)
        if name not in self.seen:
            self.seen.append(name)
        value = vals if opt.arity > 1 else (vals[0] if vals else True)
        if opt.repeated:
            self.values.setdefault(name, []).append(value)
        else:
            self.values[name] = value

    def parse(self, args):
        i = 0
        positional_only = False
        while i < len(args):
            arg = args[i]
            i += 1
            if not positional_only and arg == '--':
                positional_only = True
                continue
            if positional_only or arg == '-' or not arg.startswith('-'):
                if not arg:
                    raise CliExit("error: a value is required for '<command>...' but none was supplied\n\n" + FOOTER)
                self.commands.append(arg)
                continue
            pending = []
            if arg.startswith('--'):
                flag, equal, tail = arg[2:].partition('=')
                if flag not in LONG:
                    self.unexpected('--' + flag)
                pending = [(LONG[flag], tail if equal else None)]
            else:
                chars = arg[1:]
                while chars:
                    char, chars = chars[0], chars[1:]
                    if char not in SHORT:
                        self.unexpected('-' + char)
                    opt = SHORT[char]
                    value = None
                    if opt.optional:
                        if chars.startswith('='):
                            value, chars = chars[1:], ''
                    elif opt.arity:
                        if chars:
                            value, chars = chars.lstrip('=') if chars.startswith('=') else chars, ''
                    elif chars.startswith('='):
                        value, chars = chars[1:], ''
                    pending.append((opt, value))
            for opt, attached in pending:
                if opt.arity == 0:
                    if attached is not None:
                        self.fail(f"unexpected value '{attached}' for '{opt.label}' found; no more were expected", self.seen + [opt.long])
                    self.accept(opt, [])
                    continue
                if opt.optional:
                    self.accept(opt, [attached if attached is not None else 'all-non-zero'])
                    continue
                vals = [attached] if attached is not None else []
                while len(vals) < opt.arity and i < len(args):
                    nxt = args[i]
                    if opt.arity == 1 and nxt.startswith('-') and nxt != '-':
                        if nxt.startswith('--') and nxt.split('=')[0][2:] in LONG:
                            break
                        if nxt.startswith('-') and len(nxt) > 1 and nxt[1] in SHORT:
                            break
                        self.unexpected(nxt.split('=')[0] if nxt.startswith('--') else '-' + nxt[1])
                    vals.append(nxt)
                    i += 1
                if len(vals) != opt.arity:
                    if not vals:
                        self.missing_value(opt)
                    n = len(vals)
                    self.fail(f"{opt.arity} values required for '{opt.label}' but {n} {'was' if n == 1 else 'were'} provided")
                self.accept(opt, vals)
        # Conflicts are diagnosed in the same order that the flags were given.
        for name in self.seen:
            others = []
            for a, b in CONFLICTS:
                if name == a and b in self.values:
                    others.append(b)
                elif name == b and a in self.values:
                    others.append(a)
            if others:
                other = min(others, key=self.seen.index)
                used = [x for x in self.seen if x not in others]
                self.fail(f"the argument '{BY_NAME[name].label}' cannot be used with '{BY_NAME[other].label}'", used)
        required = []
        for name in self.seen:
            dep = DEPENDENCIES.get(name)
            if dep and dep not in self.values:
                required.append(BY_NAME[dep].label)
        if not self.commands:
            required.append('<command>...')
        if required:
            self.fail('the following required arguments were not provided:\n' + '\n'.join('  ' + x for x in required), self.seen)
        return self.values, self.commands


def integer(value, name, signed=False):
    value = str(value)
    message = None
    if not value:
        message = 'cannot parse integer from empty string'
    elif not re.fullmatch(r'[+-]?[0-9]+' if signed else r'\+?[0-9]+', value):
        message = 'invalid digit found in string'
    else:
        number = int(value)
        if number > (2**31 - 1 if signed else 2**64 - 1):
            message = 'number too large to fit in target type'
        elif signed and number < -(2**31):
            message = 'number too small to fit in target type'
        if message is None:
            return number
    raise Failure(f"Could not read numeric integer argument to '--{name}': {message}")


def parse_words(text):
    """Parse a POSIX-like command line, with no expansions or shell execution."""
    result, word = [], []
    state = None
    started = False
    i = 0
    while i < len(text):
        c = text[i]
        i += 1
        if state == "'":
            if c == "'":
                state = None
            else:
                word.append(c)
            continue
        if state == '"':
            if c == '"':
                state = None
            elif c == '\\' and i < len(text):
                nxt = text[i]
                if nxt in '\\$`"\n':
                    i += 1
                    if nxt != '\n':
                        word.append(nxt)
                else:
                    word.append(c)
            else:
                word.append(c)
            continue
        if c in ' \t\r\n':
            if started:
                result.append(''.join(word))
                word = []
                started = False
        elif c in "\"'":
            started, state = True, c
        elif c == '#':
            if started:
                word.append(c)
            else:
                while i < len(text) and text[i] != '\n':
                    i += 1
        elif c == '\\':
            if i < len(text):
                nxt = text[i]
                i += 1
                if nxt != '\n':
                    word.append(nxt)
                    started = True
            else:
                word.append('\\')
                started = True
        else:
            word.append(c)
            started = True
    if state:
        raise ValueError('missing closing quote')
    if started:
        result.append(''.join(word))
    return result


def split_values(text):
    values, word = [], []
    i = 0
    while i < len(text):
        c = text[i]
        i += 1
        if c == ',':
            values.append(''.join(word))
            word = []
        elif c == '\\' and i < len(text) and text[i] in ',\\':
            word.append(text[i])
            i += 1
        else:
            word.append(c)
    values.append(''.join(word))
    return values


def parse_decimal(text):
    error = None
    if not text:
        error = 'Invalid decimal: empty'
    elif text.count('.') > 1:
        error = 'Invalid decimal: two decimal points'
    elif not re.fullmatch(r'[+-]?[0-9_.]+', text):
        error = 'Invalid decimal: unknown character'
    elif not any(c.isdigit() for c in text):
        error = 'Invalid decimal: no digits found'
    if error:
        raise Failure(f'Error while parsing parameter scan arguments ({error})')
    try:
        number = decimal.Decimal(text.replace('_', ''))
        if number.as_tuple().exponent < -28:
            number = number.quantize(decimal.Decimal('1e-28'), rounding=decimal.ROUND_HALF_UP)
        if abs(number) > decimal.Decimal(2**96 - 1):
            raise Failure('Error while parsing parameter scan arguments (Invalid decimal: overflow from too many digits)')
        return number
    except decimal.DecimalException:
        raise Failure('Error while parsing parameter scan arguments (Invalid decimal: unknown character)')


def scan_values(args, step_text):
    name, start_text, end_text = args
    start, end = parse_decimal(start_text), parse_decimal(end_text)
    if step_text is None:
        def int64(s):
            return bool(re.fullmatch(r'[+-]?[0-9]+', s)) and -(2**63) <= int(s) < 2**63
        if not int64(start_text) or not int64(end_text):
            raise Failure("A step size is required when the range bounds are floating point numbers. The step size can be specified with the '-D/--parameter-step-size <DELTA>' parameter")
        step = decimal.Decimal(1)
    else:
        step = parse_decimal(step_text)
    if start > end:
        raise Failure('Empty parameter range')
    if step == 0:
        raise Failure('Zero is not a valid parameter step')
    if step < 0:
        raise Failure('Parameter range is too large')
    count = int((end - start) // step) + 1
    if count > 1000000:
        raise Failure('Parameter range is too large')
    values = []
    current = start
    for _ in range(count):
        # Decimal arithmetic preserves the specified scale as it advances.
        if current == 0:
            current = abs(current)
        values.append(format(current, 'f'))
        current += step
    return name, values


@dataclass
class Benchmark:
    command: str
    name: str
    parameters: dict = field(default_factory=dict)
    parameter_order: list = field(default_factory=list)
    absent_parameters: list = field(default_factory=list)
    prepare: str = None
    conclude: str = None
    setup: str = None
    cleanup: str = None
    output: str = 'null'

    def expanded(self, text):
        if text is None:
            return None
        return substitute(text, self.parameters)

    @property
    def display(self):
        if not self.absent_parameters:
            return self.name
        return self.name + ' (' + ', '.join(k + ' = ' + self.parameters[k] for k in self.absent_parameters) + ')'


def substitute(text, parameters):
    # Substitute only placeholders in the template, never in inserted values.
    if not parameters:
        return text
    pattern = re.compile('|'.join(re.escape('{' + k + '}') for k in parameters))
    return pattern.sub(lambda m: parameters[m.group()[1:-1]], text)


class Configuration:
    def __init__(self, values, commands):
        self.values = values
        self.style = values.get('style', 'auto')
        self.color = self.style in ('color', 'full') or (
            self.style == 'auto' and sys.stdout.isatty() and os.environ.get('TERM') != 'dumb' and not os.environ.get('NO_COLOR'))
        self.visible = self.style != 'none'
        self.sort = values.get('sort', 'auto')
        self.time_unit = values.get('time-unit')
        self.warmup = integer(values.get('warmup', '0'), 'warmup')
        self.min_runs = integer(values.get('min-runs', '10'), 'min-runs')
        self.max_runs = integer(values['max-runs'], 'max-runs') if 'max-runs' in values else None
        self.runs = integer(values['runs'], 'runs') if 'runs' in values else None
        if self.runs is not None:
            self.min_runs = self.max_runs = self.runs
        elif self.max_runs is not None:
            if 'min-runs' not in values:
                self.min_runs = min(self.min_runs, self.max_runs)
            if self.min_runs > self.max_runs:
                raise Failure('Conflicting requirements for the number of runs (empty range, min is larger than max)')
        self.ignore_all = False
        self.ignore_codes = set()
        if 'ignore-failure' in values:
            ignored = values['ignore-failure']
            if ignored in ('', 'all-non-zero'):
                self.ignore_all = True
            else:
                self.ignore_codes = {integer(x, 'ignore-failure', signed=True) for x in ignored.split(',')}
        shell_text = values.get('shell', 'none' if values.get('no-shell') else 'default')
        self.shell_text = '/bin/sh' if shell_text == 'default' else shell_text
        if self.shell_text == 'none':
            self.shell = None
        else:
            try:
                self.shell = parse_words(self.shell_text)
            except ValueError as e:
                raise Failure(f"Failed to parse '--shell <command>' expression as command line: {e}")
            if not self.shell:
                raise Failure("An empty command has been specified for the '--shell <command>' option")
        self.input = values.get('input', 'null')
        if self.input != 'null' and not os.path.exists(self.input):
            raise Failure(f"The file '{self.input}' specified as '--input' does not exist")
        parameter_lists = []
        if 'parameter-scan' in values:
            parameter_lists.append(scan_values(values['parameter-scan'], values.get('parameter-step-size')))
        for key, text in values.get('parameter-list', []):
            parameter_lists.append((key, split_values(text)))
        keys = [k for k, _ in parameter_lists]
        duplicates = sorted({k for k in keys if keys.count(k) > 1})
        if duplicates:
            raise Failure('Duplicate parameter names: ' + ', '.join(duplicates))
        combos = [dict()]
        if parameter_lists:
            combos = [dict(zip(reversed(keys), vals)) for vals in itertools.product(*(xs for _, xs in reversed(parameter_lists)))]
        count = len(combos) * len(commands)
        names = values.get('command-name', [])
        if parameter_lists:
            if len(names) not in (0, 1, count):
                raise Failure(f"'--command-name' has been specified {len(names)} times. It has to appear exactly once, or exactly {count} times (number of benchmarks)")
        elif len(names) > count:
            raise Failure(f'Too many --command-name options: Expected {count} at most')
        self.benchmarks = []
        self.reference = 'reference' in values
        if self.reference:
            command = values['reference']
            self.benchmarks.append(Benchmark(command, values.get('reference-name', command)))
        index = 0
        for combo in combos:
            for command in commands:
                params = {k: combo[k] for k in keys}
                name = names[0] if parameter_lists and len(names) == 1 else (names[index] if index < len(names) else command)
                self.benchmarks.append(Benchmark(
                    substitute(command, params), substitute(name, params), params,
                    keys[:], [k for k in keys if '{' + k + '}' not in command]))
                index += 1
        total = len(self.benchmarks)
        for option in ('prepare', 'conclude', 'output'):
            items = values.get(option, [])
            if len(items) not in (0, 1, total):
                raise Failure(f"The '--{option}' option has to be provided just once or N times, where N={total} is the number of benchmark commands (including a potential reference).")
            for i, bench in enumerate(self.benchmarks):
                value = items[0] if len(items) == 1 else (items[i] if items else None)
                if option == 'output':
                    bench.output = value if value is not None else ('inherit' if values.get('show-output') else 'null')
                else:
                    setattr(bench, option, bench.expanded(value))
        for bench in self.benchmarks:
            bench.setup = bench.expanded(values.get('setup'))
            bench.cleanup = bench.expanded(values.get('cleanup'))


MICRO_WARNING = ('Command took less than 5 ms to complete. Note that the results might be inaccurate because hyperfine can not calibrate the shell startup time much more precise than this limit. You can try to use the `-N`/`--shell=none` option to disable the shell completely.')
OUTLIER_WARNING = ("Statistical outliers were detected. Consider re-running this benchmark on a quiet system without any interferences from other programs. It might help to use the '--warmup' or '--prepare' options.")
FAILURE_HINT = ("Use the '-i'/'--ignore-failure' option if you want to ignore this. Alternatively, use the '--show-output' option to debug what went wrong.")


def os_error(e):
    return (e.strerror or os.strerror(e.errno)) + f' (os error {e.errno})'


def paint(text, style, enabled):
    return '\x1b[' + style + 'm' + str(text) + '\x1b[0m' if enabled else str(text)


def chosen_unit(seconds, forced=None):
    if forced:
        return forced
    if seconds < 0.001:
        return 'microsecond'
    if seconds < 1:
        return 'millisecond'
    return 'second'


def format_time(seconds, unit, padded=False):
    if unit == 'second':
        n, precision, suffix = seconds, 3, 's'
    elif unit == 'millisecond':
        n, precision, suffix = seconds * 1000, 1, 'ms'
    else:
        n, precision, suffix = seconds * 1000000, 1, 'µs'
    width = 6 if padded and unit == 'second' else (5 if padded else 0)
    return f'{n:{width}.{precision}f} {suffix}'


def table_time(seconds, unit):
    return format_time(seconds, unit).rsplit(' ', 1)[0]


def divide(a, b):
    if b == 0:
        return float('nan') if a == 0 else float('inf')
    return a / b


def numfmt(number, digits=2, width=0):
    if math.isnan(number):
        return 'NaN'.rjust(width)
    return f'{number:{width}.{digits}f}'


def relative(result, base):
    if result is base:
        return 1.0, None
    ratio = divide(result['mean'], base['mean'])
    spread = None
    if result['stddev'] is not None and base['stddev'] is not None:
        spread = ratio * math.sqrt(divide(result['stddev'], result['mean'])**2 + divide(base['stddev'], base['mean'])**2)
    return ratio, spread


class Reporter:
    def __init__(self, config):
        self.config = config

    def c(self, text, style):
        return paint(text, style, self.config.color)

    def heading(self, i, bench):
        if self.config.visible:
            print(self.c('Benchmark ', '1') + self.c(str(i), '1') + ': ' + bench.display, flush=True)

    def result(self, result):
        if not self.config.visible:
            return
        unit = chosen_unit(result['mean'], self.config.time_unit)
        mean = self.c(format_time(result['mean'], unit, True), '1;32')
        usage = '    [User: ' + self.c(format_time(result['user'], unit), '34') + ', System: ' + self.c(format_time(result['system'], unit), '34') + ']'
        if result['stddev'] is None:
            print('  Time (' + self.c('abs', '1;32') + ' ≡):        ' + mean + '           ' + usage)
        else:
            stddev = self.c(format_time(result['stddev'], unit, True), '32')
            print('  Time (' + self.c('mean', '1;32') + ' ± ' + self.c('σ', '32') + '):     ' + mean + ' ± ' + stddev + usage)
            print('  Range (' + self.c('min', '36') + ' … ' + self.c('max', '35') + '):   ' + self.c(format_time(result['min'], unit, True), '36') + ' … ' + self.c(format_time(result['max'], unit, True), '35') + '    ' + self.c(str(len(result['times'])) + ' runs', '2'))
        print(' ', flush=True)

    def warnings(self, result):
        warnings = []
        if self.config.shell and result['mean'] < 0.005:
            warnings.append(MICRO_WARNING)
        if any(x != 0 for x in result['exit_codes']):
            warnings.append('Ignoring non-zero exit code.')
        times = result['times']
        if len(times) >= 3:
            median = statistics.median(times)
            mad = statistics.median([abs(t - median) for t in times])
            # Robust outlier classification, unaffected by a few very slow runs.
            outliers = [i for i, t in enumerate(times) if abs(t - median) > 3 * 1.4826 * mad]
            if outliers:
                if 0 in outliers and times[0] > median and times[0] == max(times):
                    first = format_time(times[0], chosen_unit(times[0], self.config.time_unit))
                    message = f'The first benchmarking run for this command was significantly slower than the rest ({first}). This could be caused by (filesystem) caches that were not filled until after the first run. '
                    if self.config.warmup:
                        message += "You are already using the '--warmup' option which helps to fill these caches before the actual benchmark. You can either try to increase the warmup count further or re-run this benchmark on a quiet system in case it was a random outlier. "
                    else:
                        message += "You should consider using the '--warmup' option to fill those caches before the actual benchmark. "
                    message += "Alternatively, consider using the '--prepare' option to clear the caches before each timing run."
                    warnings.append(message)
                else:
                    warnings.append(OUTLIER_WARNING)
        if warnings:
            sys.stderr.write(' \n')
            for warning in warnings:
                sys.stderr.write('  ' + self.c('Warning', '33') + ': ' + warning + '\n')
            sys.stderr.flush()

    def summary(self, results, benchmarks):
        if not self.config.visible or len(results) < 2:
            return
        base = results[0] if self.config.reference else min(results, key=lambda x: x['mean'])
        base_index = next(i for i, r in enumerate(results) if r is base)
        if self.config.sort == 'command':
            print(self.c('Relative speed comparison', '1'))
            for i, r in enumerate(results):
                ratio, spread = relative(r, base) if r['mean'] >= base['mean'] else relative(base, r)
                text = '  ' + self.c(numfmt(ratio, 2, 10), '1;32')
                if spread is None:
                    text += '        '
                else:
                    text += ' ± ' + self.c(numfmt(spread, 2, 5), '32')
                print(text + '  ' + benchmarks[i].display)
        else:
            print(self.c('Summary', '1'))
            print('  ' + self.c(benchmarks[base_index].display, '36') + ' ran')
            for i in sorted(range(len(results)), key=lambda n: results[n]['mean']):
                r = results[i]
                if r is base:
                    continue
                faster = r['mean'] >= base['mean']
                ratio, spread = relative(r, base) if faster else relative(base, r)
                text = self.c('    ' + numfmt(ratio), '1;32')
                if spread is not None:
                    text += ' ± ' + self.c(numfmt(spread), '32')
                print(text + ' times ' + ('faster' if faster else 'slower') + ' than ' + self.c(benchmarks[i].display, '35'))
        sys.stdout.flush()


class Executor:
    def __init__(self, config):
        self.config = config
        self.calibration = (0.0, 0.0, 0.0)

    def argv(self, command):
        if self.config.shell:
            return self.config.shell + ['-c', command]
        try:
            words = parse_words(command)
        except ValueError as e:
            raise Failure(f"Failed to parse command '{command}': {e}")
        if not words:
            raise Failure('Can not execute empty command')
        return words

    def execute(self, command, output='null', iteration=None, calibrating=False):
        argv = self.argv(command)
        fds = []
        input_path = '/dev/null' if calibrating or self.config.input == 'null' else self.config.input
        output = 'null' if calibrating else output
        env = None
        if iteration is not None:
            env = os.environ.copy()
            env['HYPERFINE_ITERATION'] = iteration
        try:
            inp = os.open(input_path, os.O_RDONLY)
            fds.append(inp)
            out = err = None
            if output in ('null', 'pipe'):
                if output == 'pipe':
                    out = err = subprocess.PIPE
                else:
                    out = err = os.open('/dev/null', os.O_WRONLY)
                    fds.append(out)
            elif output != 'inherit':
                out = os.open(output, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o666)
                err = os.open('/dev/null', os.O_WRONLY)
                fds += [out, err]
            start = time.perf_counter_ns()
            try:
                child = subprocess.Popen(argv, stdin=inp, stdout=out, stderr=err, env=env)
            except (OSError, ValueError) as e:
                if isinstance(e, OSError):
                    raise Failure(f"Failed to run command '{command}': {os_error(e)}")
                raise Failure(f"Failed to run command '{command}': {e}")
            if output == 'pipe':
                # Drain both streams without retaining unbounded command output.
                import selectors
                selector = selectors.DefaultSelector()
                for pipe in (child.stdout, child.stderr):
                    os.set_blocking(pipe.fileno(), False)
                    selector.register(pipe, selectors.EVENT_READ)
                while selector.get_map():
                    for key, _ in selector.select():
                        if not os.read(key.fd, 65536):
                            selector.unregister(key.fileobj)
                            key.fileobj.close()
                selector.close()
            while True:
                try:
                    _, status, usage = os.wait4(child.pid, 0)
                    break
                except InterruptedError:
                    pass
            end = time.perf_counter_ns()
            code = os.waitstatus_to_exitcode(status)
            child.returncode = code
            return ((end - start) / 1e9, usage.ru_utime, usage.ru_stime, usage.ru_maxrss * 1024, code)
        except OSError as e:
            raise Failure(os_error(e))
        finally:
            for fd in fds:
                os.close(fd)

    def calibrate(self):
        if not self.config.shell:
            return
        samples = []
        try:
            for _ in range(50):
                result = self.execute('', calibrating=True)
                if result[4] != 0:
                    raise Failure('calibration command failed')
                samples.append(result)
        except Failure:
            raise Failure(f"Could not measure shell execution time. Make sure you can run '{self.config.shell_text} -c \"\"'.")
        self.calibration = tuple(sum(s[i] for s in samples) / len(samples) for i in range(3))

    def hook(self, command, role, output):
        if command is None:
            return
        try:
            result = self.execute(command, output)
            if result[4] == 0:
                return
        except Failure:
            pass
        raise Failure(f"The {role} command terminated with a non-zero exit code. Append ' || true' to the command if you are sure that this can be ignored.")

    def check_status(self, code, iteration, warmup):
        if code == 0 or self.config.ignore_all or code in self.config.ignore_codes:
            return
        phase = 'warmup' if warmup else 'benchmark'
        location = 'the first ' + phase + ' run' if iteration == 0 else phase + ' iteration ' + str(iteration)
        if code < 0:
            message = 'The process has been terminated by a signal'
        else:
            message = f'Command terminated with non-zero exit code {code}'
        raise Failure(message + ' in ' + location + '. ' + FAILURE_HINT)

    def benchmark(self, bench):
        self.hook(bench.setup, 'setup', bench.output)
        for i in range(self.config.warmup):
            self.hook(bench.prepare, 'preparation', bench.output)
            r = self.execute(bench.command, bench.output, f'warmup-{i}')
            self.check_status(r[4], i, True)
            self.hook(bench.conclude, 'conclusion', bench.output)
        measurements = []
        total = 0.0
        target = self.config.runs
        i = 0
        while True:
            self.hook(bench.prepare, 'preparation', bench.output)
            r = self.execute(bench.command, bench.output, str(i))
            self.check_status(r[4], i, False)
            self.hook(bench.conclude, 'conclusion', bench.output)
            measurements.append(r)
            total += r[0]
            i += 1
            if target is not None:
                if i == target:
                    break
            else:
                if self.config.max_runs is not None and i == self.config.max_runs:
                    break
                if i >= self.config.min_runs and total >= 3.0:
                    break
        times = [max(0.0, m[0] - self.calibration[0]) for m in measurements]
        user = sum(max(0.0, m[1] - self.calibration[1]) for m in measurements) / len(measurements)
        system = sum(max(0.0, m[2] - self.calibration[2]) for m in measurements) / len(measurements)
        result = {
            'command': bench.name,
            'mean': sum(times) / len(times),
            'stddev': statistics.stdev(times) if len(times) > 1 else None,
            'median': statistics.median(times),
            'user': user,
            'system': system,
            'min': min(times),
            'max': max(times),
            'times': times,
            'memory_usage_byte': [m[3] for m in measurements],
            'exit_codes': [m[4] if m[4] >= 0 else -1 for m in measurements],
        }
        if bench.parameters:
            result['parameters'] = dict(sorted(bench.parameters.items()))
        return result


EXPORT_ORDER = ('asciidoc', 'json', 'csv', 'markdown', 'orgmode')


def float_text(number):
    if number == 0:
        return '0'
    text = repr(float(number))
    if 'e' in text:
        text = format(decimal.Decimal(text), 'f')
    if text.endswith('.0'):
        text = text[:-2]
    return text


class Exporters:
    def __init__(self, config):
        self.config = config
        self.destinations = {}
        for kind in EXPORT_ORDER:
            path = config.values.get('export-' + kind)
            if path is None:
                continue
            if path == '-':
                self.destinations[kind] = None
            else:
                try:
                    self.destinations[kind] = open(path, 'w', encoding='utf-8', newline='')
                except OSError as e:
                    raise Failure(f"Could not create export file '{path}': {os_error(e)}")

    def json(self, results):
        # The standard JSON structure includes individual measurements as well
        # as the aggregate statistics, with no parameters key when absent.
        return json.dumps({'results': results}, ensure_ascii=False, indent=2, allow_nan=False) + '\n'

    def csv(self, results):
        data = io.StringIO(newline='')
        writer = csv.writer(data, lineterminator='\n')
        keys = sorted(results[0].get('parameters', {}))
        fields = ['command', 'mean', 'stddev', 'median', 'user', 'system', 'min', 'max']
        writer.writerow(fields + ['parameter_' + k for k in keys])
        for r in results:
            params = r.get('parameters', {})
            if len(params) != len(keys):
                raise Failure(f'CSV error: found record with {8 + len(params)} fields, but the previous record has {8 + len(keys)} fields')
            writer.writerow([r['command']] + [float_text(r[k] or 0) for k in fields[1:]] + [params[k] for k in sorted(params)])
        return data.getvalue()

    def markup(self, results, kind):
        results = sorted(results, key=lambda x: x['mean']) if self.config.sort == 'mean-time' else results
        fastest = min(results, key=lambda x: x['mean'])
        unit = chosen_unit(min(r['mean'] for r in results), self.config.time_unit)
        symbol = {'second': 's', 'millisecond': 'ms', 'microsecond': 'µs'}[unit]
        headers = ['Command', f'Mean [{symbol}]', f'Min [{symbol}]', f'Max [{symbol}]', 'Relative']
        rows = []
        for r in results:
            name = r['command'].replace('|', '\\|')
            quote = '=' if kind == 'orgmode' else '`'
            mean = table_time(r['mean'], unit)
            if r['stddev'] is not None:
                mean += ' ± ' + table_time(r['stddev'], unit)
            ratio, spread = relative(r, fastest)
            rel = numfmt(ratio)
            if spread is not None:
                rel += ' ± ' + numfmt(spread)
            rows.append([quote + name + quote, mean, table_time(r['min'], unit), table_time(r['max'], unit), rel])
        if kind == 'markdown':
            return '| ' + ' | '.join(headers) + ' |\n|:---|---:|---:|---:|---:|\n' + ''.join('| ' + ' | '.join(row) + ' |\n' for row in rows)
        if kind == 'orgmode':
            def line(row):
                return '| ' + row[0] + '  |  ' + ' |  '.join(row[1:]) + ' |\n'
            return line(headers) + '|--+--+--+--+--|\n' + ''.join(line(row) for row in rows)
        text = '[cols="<,>,>,>,>"]\n|===\n' + ''.join('| ' + v + ' \n' for v in headers)
        for row in rows:
            text += '\n' + ''.join('| ' + v + ' \n' for v in row)
        return text + '|===\n'

    def render(self, kind, results):
        if kind == 'json':
            return self.json(results)
        if kind == 'csv':
            return self.csv(results)
        return self.markup(results, kind)

    def update(self, results):
        for kind, f in self.destinations.items():
            if f is None:
                continue
            data = self.render(kind, results)
            try:
                f.seek(0)
                f.write(data)
                f.truncate()
                f.flush()
            except OSError as e:
                raise Failure(os_error(e))

    def finish(self, results):
        for kind, f in self.destinations.items():
            if f is None:
                data = self.render(kind, results)
                sys.stdout.write('\n' + data + '\n')
            else:
                f.close()
        sys.stdout.flush()


def main():
    config = None
    try:
        decimal.getcontext().prec = 100
        values, commands = Parser().parse(sys.argv[1:])
        config = Configuration(values, commands)
        exporters = Exporters(config)
        reporter = Reporter(config)
        executor = Executor(config)
        executor.calibrate()
        results = []
        for i, bench in enumerate(config.benchmarks, 1):
            reporter.heading(i, bench)
            result = executor.benchmark(bench)
            reporter.result(result)
            reporter.warnings(result)
            executor.hook(bench.cleanup, 'cleanup', bench.output)
            results.append(result)
            exporters.update(results)
        reporter.summary(results, config.benchmarks)
        exporters.finish(results)
        return 0
    except CliExit as e:
        stream = sys.stdout if e.stdout else sys.stderr
        stream.write(e.text)
        stream.flush()
        return e.code
    except Failure as e:
        color = config.color if config else False
        sys.stderr.write(paint('Error:', '31', color) + ' ' + str(e) + '\n')
        sys.stderr.flush()
        return 1
    except KeyboardInterrupt:
        return 130
    except BrokenPipeError:
        return 1


