    """Deterministic two-space JSON, including compact decimal float notation."""
    indent = '  ' * level
    next_indent = indent + '  '
    if isinstance(value, dict):
        if not value:
            return '{}'
        return '{\\n' + ',\\n'.join(
            next_indent + json.dumps(k, ensure_ascii=False) + ': ' + pretty_json(v, level + 1)
            for k, v in value.items()) + '\\n' + indent + '}'
    if isinstance(value, list):
        if not value:
            return '[]'
        return '[\\n' + ',\\n'.join(next_indent + pretty_json(v, level + 1) for v in value) + '\\n' + indent + ']'
    if isinstance(value, float):
        if not math.isfinite(value):
            return 'null'
        text = repr(value)
        if 1e-5 <= abs(value) < 1e16 and 'e' in text:
            return format(decimal.Decimal(text), 'f')
        return re.sub(r'e([+-])0+(\\d+)', r'e\\1\\2', text)
    return json.dumps(value, ensure_ascii=False)


def csv_record(fields):
    def escape(value):
        text = str(value)
        if any(c in text for c in ',"\\r\\n'):
            return '"' + text.replace('"', '""') + '"'
        return text
    return ','.join(escape(value) for value in fields) + '\\n'
'''
